description?: string, // maxLength: 20000
type: "singleCollaborator" | "multipleCollaborators" | "singleLineText" | "email" | "url" | "multilineText" | "phoneNumber" | "richText" | "barcode" | "multipleAttachments",
}
 | {
// Field names must be unique within the table (case-insensitive).
