},
}
 | {
// Field names must be unique within the table (case-insensitive).
name: string, // minLength: 1
description?: string, // maxLength: 20000
type: "singleSelect" | "multipleSelects",
options: {
// maxItems: 10000
choices: Array<
{
name: string,
// Colors are auto-assigned if omitted.
color?: "blueLight2" | "cyanLight2" | "tealLight2" | "greenLight2" | "yellowLight2" | "orangeLight2" | "redLight2" | "pinkLight2" | "purpleLight2" | "grayLight2" | "blueLight1" | "cyanLight1" | "tealLight1" | "greenLight1" | "yellowLight1" | "orangeLight1" | "redLight1" | "pinkLight1" | "purpleLight1" | "grayLight1" | "blueBright" | "cyanBright" | "tealBright" | "greenBright" | "yellowBright" | "orangeBright" | "redBright" | "pinkBright" | "purpleBright" | "grayBright" | "blueDark1" | "cyanDark1" | "tealDark1" | "greenDark1" | "yellowDark1" | "orangeDark1" | "redDark1" | "pinkDark1" | "purpleDark1" | "grayDark1",
}
>,
},
}
 | {
// Field names must be unique within the table (case-insensitive).
name: string, // minLength: 1
description?: string, // maxLength: 20000
type: "number",
options: {
// Number of decimal places.
precision: integer, // minimum: 0, maximum: 8
},
}
 | {
// Field names must be unique within the table (case-insensitive).
name: string, // minLength: 1
description?: string, // maxLength: 20000
type: "percent",
options: {
// Number of decimal places.
precision: integer, // minimum: 0, maximum: 8
},
}
 | {
// Field names must be unique within the table (case-insensitive).
name: string, // minLength: 1
description?: string, // maxLength: 20000
type: "currency",
options: {
// Number of decimal places.
precision: integer, // minimum: 0, maximum: 7
// Currency symbol, e.g. "$", "€", "£", "¥".
symbol: string, // maxLength: 100
},
}
 | {
// Field names must be unique within the table (case-insensitive).
name: string, // minLength: 1
description?: string, // maxLength: 20000
type: "duration",
options: {
// Display format for the duration value.
durationFormat: "h:mm" | "h:mm:ss" | "h:mm:ss.S" | "h:mm:ss.SS" | "h:mm:ss.SSS",
},
}
 | {
// Field names must be unique within the table (case-insensitive).
name: string, // minLength: 1
description?: string, // maxLength: 20000
type: "date",
options: {
dateFormat: {
// Date format preset: "local" (l), "friendly" (LL), "us" (M/D/YYYY), "european" (D/M/YYYY), "iso" (YYYY-MM-DD).
name: "local" | "friendly" | "us" | "european" | "iso",
// Format is optional, but must match name if provided.
format?: "l" | "LL" | "M/D/YYYY" | "D/M/YYYY" | "YYYY-MM-DD",
},
},
}
 | {
// Field names must be unique within the table (case-insensitive).
name: string, // minLength: 1
description?: string, // maxLength: 20000
type: "dateTime",
options: {
dateFormat: {
// Date format preset: "local" (l), "friendly" (LL), "us" (M/D/YYYY), "european" (D/M/YYYY), "iso" (YYYY-MM-DD).
name: "local" | "friendly" | "us" | "european" | "iso",
// Format is optional, but must match name if provided.
