},
timeFormat: {
// Time format preset: "12hour" (h:mma), "24hour" (HH:mm).
name: "12hour" | "24hour",
// Format is optional, but must match name if provided.
format?: "h:mma" | "HH:mm",
},
// IANA time zone identifier (e.g., "America/New_York", "Europe/London", "UTC"). Required for dateTime fields.
timeZone: string,
},
}
 | {
// Field names must be unique within the table (case-insensitive).
name: string, // minLength: 1
description?: string, // maxLength: 20000
type: "rating",
options: {
// Rating color. Use "yellowBright" for a standard rating.
color: "yellowBright" | "orangeBright" | "redBright" | "pinkBright" | "purpleBright" | "blueBright" | "cyanBright" | "tealBright" | "greenBright" | "grayBright",
// Rating icon. Use "star" for a standard rating.
