},
}
// The server assigns each record a unique incrementing number; existing records are numbered 1..N on field creation. There are no writable options.
 | {
// Field names must be unique within the table (case-insensitive).
name: string, // minLength: 1
description?: string, // maxLength: 20000
type: "autoNumber",
}

>,
