// To get an automationId, use the create_automation tool.
automationId: string, // pattern: /^wfl[A-Za-z0-9]{14}$/
// Return only runs with this status. Use "failure" when diagnosing.
status?: "success" | "failure" | "canceled",
// Returns runs queued before this time. Must be an ISO 8601 datetime with either Z or an explicit timezone offset.
startedBefore?: string, // format: "date-time"
// Number of runs to return. Defaults to 20, maximum 100.
pageSize?: integer, // minimum: 1, maximum: 100
// Pass nextCursor from a previous response to fetch the following page.
// Must start with "wfx" and is 17 characters long.
// Example: "wfxR9dBiKHQokh1Jt".
cursor?: string, // pattern: /^wfx[A-Za-z0-9]{14}$/
}): Promise<{
// Matching runs, newest first.
runs: Array<
{
// The ID of this run.
runId: string,
// Outcome of the run.
status: "inProgress" | "success" | "failure" | "canceled" | "skipped",
// ISO 8601 timestamp of when the run was queued. On a base with a backlog this can be well
// before the automation actually started doing work.
startedTime: string,
// ISO 8601 timestamp of when the run ended.
finishedTime: string | null,
// Time from queueing to finishing.
durationMs: number | null,
// The published version of the automation that ran.
deploymentId: string,
// Details of what broke, covering both action steps and decision steps such as conditionals
// and repeating groups.
//
// Only the most recent failed runs on a page get a step looked up, so on a page with many
// failures the older ones can all report null together.
failure:
 | {
// The step that failed, usually matching a node key returned by
// list_automations and get_automation.
nodeKey: string,
// Category of the failure.
code: "INPUT_EXPRESSION_EVALUATION_FAILURE" | "INPUT_VALIDATION_FAILURE" | "UNEXPECTED_CONTEXT" | "EXTERNAL_ACCOUNT_FAILURE" | "DEPENDENT_INPUT_KEY_MISSING" | "NOT_IMPLEMENTED" | "APPLICATION_DELETED" | "WORKSPACE_DELETED" | "WORKFLOW_IN_DENY_LIST" | "BASE_MIGRATED_TO_NEW_SHARD" | "APPLICATION_EKM_REVOKED" | "NODE_EXECUTION_CANCELED" | "WORKFLOW_GRAPH_EXECUTION_MARKED_AS_FAILED" | "EXECUTION_LIMIT_REACHED" | "FAILED_TO_RECORD_RESULTS" | "FAILED_TO_UPDATE_METADATA" | "UNREACHABLE_NODE" | "RATE_LIMITED" | "UNKNOWN_TRIGGER_REGISTRATION_ID" | "INCORRECT_TRIGGER_REGISTRATION_STATUS" | "INVALID_WEB_HOOK_SIGNATURE" | "INVALID_WEB_HOOK_BODY_BASE64" | "WEB_HOOK_PAYLOAD_ERROR" | "UNPROCESSABLE_WEB_HOOK_PAYLOAD" | "INVALID_TRIGGER_STATE" | "UNEXPECTED_NUMBER_OF_NEXT_NODES" | "INVALID_NEXT_NODE_SELECTED" | "MISSING_MATCHING_REDUCER_NODE" | "DECISION_TEST_BRANCH_NOT_SELECTED" | "INVALID_DECISION_TEST_METADATA" | "ERRORS_IN_PARENT_BRANCHES" | "FAN_OUT_BRANCH_LIMIT_REACHED" | "FAILED_TO_ACQUIRE_LOCK" | "PAYLOAD_TOO_LARGE" | "NODE_SPECIFIC_FAILURE" | "THROWN_EXCEPTION_FAILURE" | "UNIT_TEST_EXPECTED_FAILURE",
// A narrower code for the failure, including for failures that originated at an external service.
specificCode: string | null,
}
 | null
,
}
>,
// Pass back as cursor to fetch the next page. Null when there are no more runs.
