// To get baseId, use the search_bases or list_bases tool.
baseId: string, // pattern: /^app[A-Za-z0-9]{14}$/
// The ID of the action to revert, from a prior eligible tool result in this session.
// Must start with "act" and is 17 characters long.
// Example: "actZOTa3BDHxlJNzf".
actionId: string, // pattern: /^act[A-Za-z0-9]{14}$/
}): Promise<{
// The actionId that was reverted.
