mcp__AppDeploy__upload_resources(args: {
// Optional app scope; uploading does not bind or deploy.
app_id?: string, // minLength: 1
// Set to "2.13", the MCP version in this tool's description. Use this tool's version, not another tool's version.
mcp_version?: string, // minLength: 1, maxLength: 32, pattern: /^\d+\.\d+(?:\.\d+)?$/
// Required for a new entry. Binary files under public/resources/ only.
// minItems: 1, maxItems: 20
resources?: Array<
{
accept?: string, // maxLength: 200
name?: string, // maxLength: 300
// Preferred picker source; ChatGPT Library falls back to device upload when unavailable.
preferred_source?: "computer" | "chatgpt_library",
// Identifies an app favicon; omit for other resources.
purpose?: "favicon",
required?: boolean,
target_path: string, // minLength: 1
}
>,
// Request a fresh transfer ticket after a failed transfer, keeping the entry ID.
retry?: boolean,
// Resume an existing resource entry.
upload_id?: string, // minLength: 1
}): Promise<unknown>;
