//
// Input schema for updating an entity schema.
{
// Appid
//
// The ID of the app
appId: string,
// Entityname
//
// Entity name to update (alphanumeric)
entityName: string, // maxLength: 63, pattern: /^\w+$/
// Entityschema
//
// Updated JSON schema definition. Fields and constraints not included in this object will be removed. However, security rules (entity-level 'rls' and per-field 'rls' inside properties) are automatically preserved when omitted — include them explicitly to change or clear them.
entitySchema: { [key: string]: any },
}): Promise<unknown>;
